import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, texture, positionLocal, normalLocal, uniform, mix } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    CircleGeometry,
    Color,
    PointLight
  } = THREE;

  const root = new Group();
  root.name = config.id ?? 'features-list-row';

  const resources = [];
  const timelines = [];
  const primitiveResults = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const addResource = (resource) => {
    if (resource) resources.push(resource);
    return resource;
  };

  const makeBasicMaterial = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    addResource(material);
    return material;
  };

  const makeStandardMaterial = (options = {}) => {
    const material = new MeshStandardNodeMaterial(options);
    addResource(material);
    return material;
  };

  const backdropGeometry = addResource(new PlaneGeometry(7, 6, 1, 1));
  const backdropMaterial = makeBasicMaterial();
  const gradientBottom = uniform(new Color(colors.surface));
  const gradientMiddle = uniform(new Color(colors.ink));
  const gradientTop = uniform(new Color(colors.ink));

  const gradientT = uv().y;
  backdropMaterial.colorNode = mix(
    mix(gradientBottom, gradientMiddle, gradientT.mul(0.58)),
    gradientTop,
    gradientT
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'designed-gradient-backdrop';
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const shadowGeometry = addResource(new CircleGeometry(1.35, 48));
  const shadowMaterial = makeBasicMaterial({
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
    color: colors.surface
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.name = 'contact-shadow';
  contactShadow.scale.set(2.05, 0.34, 1);
  contactShadow.position.set(0, -0.47, -0.12);
  root.add(contactShadow);

  const panelGeometry = addResource(new BoxGeometry(5.65, 0.82, 0.1, 8, 4, 2));
  const panelMaterial = makeStandardMaterial({
    color: colors.ink,
    roughness: 0.64,
    metalness: 0.38
  });
  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.name = 'machined-feature-row';
  root.add(panel);

  const edgeGeometry = addResource(new BoxGeometry(0.035, 0.64, 0.025));
  const edgeMaterial = makeBasicMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.18,
    depthWrite: false
  });
  const accentEdge = new Mesh(edgeGeometry, edgeMaterial);
  accentEdge.name = 'focus-accent-edge';
  accentEdge.position.set(-2.71, 0, 0.085);
  root.add(accentEdge);

  const dividerGeometry = addResource(new BoxGeometry(5.1, 0.012, 0.018));
  const dividerMaterial = makeBasicMaterial({
    color: colors.paper,
    transparent: true,
    opacity: 0.22,
    depthWrite: false
  });
  const divider = new Mesh(dividerGeometry, dividerMaterial);
  divider.name = 'subtle-divider';
  divider.position.set(0, -0.405, 0.09);
  root.add(divider);

  const foregroundAccentGeometry = addResource(new BoxGeometry(0.22, 0.035, 0.04));
  const foregroundAccentMaterial = makeBasicMaterial({
    color: colors.accent,
    transparent: true,
    opacity: 0.9
  });
  const foregroundAccent = new Mesh(
    foregroundAccentGeometry,
    foregroundAccentMaterial
  );
  foregroundAccent.name = 'foreground-signal-accent';
  foregroundAccent.position.set(2.48, 0.27, 0.12);
  root.add(foregroundAccent);

  const rimLight = new PointLight(new Color(colors.accent), 0.72, 5.5, 2);
  rimLight.position.set(2.4, 1.1, 1.8);
  root.add(rimLight);

  const textItems = config.textContent ?? visualSpec.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'feature-row-text';
  root.add(textGroup);

  for (const item of textItems) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? 'body';
    const isCaption = role === 'caption' || role === 'meta' || role === 'label';
    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize:
        item.typography?.fontSize ??
        (role === 'headline' || role === 'title' ? 34 : isCaption ? 16 : 20),
      color: isCaption ? colors.paper : colors.paper,
      align: role === 'meta' ? 'right' : 'left',
      letterSpacingPx: isCaption ? 1.2 : 0
    });

    if (role === 'meta') {
      textObject.position.set(2.25, 0.08, 0.11);
    } else if (role === 'label' || role === 'caption') {
      textObject.position.set(-2.42, -0.17, 0.11);
    } else {
      textObject.position.set(-2.42, 0.08, 0.11);
    }

    textGroup.add(textObject);
  }

  const imageGeometry = addResource(new PlaneGeometry(5.5, 0.77, 64, 64));
  const imageMaterial = makeBasicMaterial({
    transparent: true,
    opacity: 0.28,
    depthWrite: false
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.name = 'parallax-image-plane';
  imagePlane.position.z = 0.07;
  root.add(imagePlane);

  let loadedImageTexture;
  let loadedDepthTexture;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) {
        tex?.dispose?.();
        return;
      }
      loadedImageTexture = addResource(tex);
      imageMaterial.colorNode = texture(loadedImageTexture, uv());
      imageMaterial.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTexture) => {
      if (disposed) {
        depthTexture?.dispose?.();
        return;
      }

      loadedDepthTexture = addResource(depthTexture);
      imageMaterial.positionNode = positionLocal.add(
        normalLocal.mul(texture(loadedDepthTexture, uv()).r.mul(0.075))
      );
      imageMaterial.needsUpdate = true;
    });
  }

  const baseY = root.position.y;
  const baseRotationX = root.rotation.x;
  const baseRotationY = root.rotation.y;

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.position,
    { y: baseY + 0.4 },
    { y: baseY, duration: 0.7, ease: 'power3.out' }
  );
  entrance.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<'
  );
  entrance.play();
  timelines.push(entrance);

  const handlers = {};

  handlers.hover = (active = true) => {
    const entering = active !== false;
    const hoverTimeline = gsap.timeline();
    hoverTimeline.to(root.position, {
      y: entering ? baseY + 0.15 : baseY,
      duration: 0.3,
      ease: 'power3.out'
    });
    hoverTimeline.to(
      root.rotation,
      {
        x: entering ? baseRotationX - 0.035 : baseRotationX,
        y: entering ? baseRotationY + 0.035 : baseRotationY,
        duration: 0.3,
        ease: 'power3.out'
      },
      '<'
    );
    hoverTimeline.to(
      accentEdge.material,
      { opacity: entering ? 0.72 : 0.18, duration: 0.25, ease: 'power2.out' },
      '<'
    );
    timelines.push(hoverTimeline);
  };

  handlers.focus = (active = true) => {
    const focused = active !== false;
    const focusTimeline = gsap.timeline();
    focusTimeline.to(accentEdge.material, {
      opacity: focused ? 1 : 0.18,
      duration: 0.22,
      ease: 'power2.out'
    });
    timelines.push(focusTimeline);
  };

  handlers.pointermove = (payload = {}) => {
    const px = Number(payload.x ?? payload.clientX ?? 0);
    const py = Number(payload.y ?? payload.clientY ?? 0);
    const nx = Number.isFinite(px) ? Math.max(-1, Math.min(1, px)) : 0;
    const ny = Number.isFinite(py) ? Math.max(-1, Math.min(1, py)) : 0;

    const parallaxTimeline = gsap.timeline();
    parallaxTimeline.to(root.rotation, {
      x: baseRotationX + ny * 0.045,
      y: baseRotationY + nx * 0.055,
      duration: 0.28,
      ease: 'power2.out'
    });
    timelines.push(parallaxTimeline);
  };

  handlers.click = () => {
    const pressTimeline = gsap.timeline();
    pressTimeline.to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    });
    pressTimeline.to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.36,
      ease: 'back.out(2)'
    });
    timelines.push(pressTimeline);

    ctx.emit('hub-features.select', {
      id: config.id ?? 'hub-features',
      checkoutUrl: config.data?.checkoutUrl ?? config.checkoutUrl
    });
  };

  for (const primitive of config.cinematicPrimitives ?? []) {
    if (!primitive?.name || !ctx.primitives?.[primitive.name]) continue;
    const result = ctx.primitives[primitive.name](root, primitive.params);
    if (result) primitiveResults.push(result);
  }

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) timeline?.kill?.();
    for (const result of primitiveResults) result?.cleanup?.();

    for (const child of root.children) {
      child.traverse?.((object) => {
        if (object.geometry && !resources.includes(object.geometry)) {
          object.geometry.dispose?.();
        }
        if (object.material && !resources.includes(object.material)) {
          if (Array.isArray(object.material)) {
            object.material.forEach((material) => material.dispose?.());
          } else {
            object.material.dispose?.();
          }
        }
      });
    }

    for (const resource of resources) resource?.dispose?.();
  };

  return root;
}
